"""Export verified numeric SW Blood Tournament terrain; never execute map code/art.
Run after extracting the pinned map into outputs/bloody-tournament-reference/original.
"""
from pathlib import Path
import collections,hashlib,importlib.util,json,re,struct
ROOT=Path(__file__).resolve().parents[1]
SOURCE=ROOT/'outputs/bloody-tournament-reference/original'
EXPECTED={'war3map.w3e':'bc7bef0cef441892f058273a18d837fef1d2f0aa774f83635ab940ff9835a90d','war3map.doo':'7108cab622df397fde2806fa12b32fbba534eb5c2260119abf2591197cc1ace4','war3map.wpm':'181af565047c506bd21d457641cf7ea5866f2d4ea7af3a259ddc854f7099a0a4','war3map.j':'4985a252778a674930df8dcb0e6e3a50b7fd60a0813319b56fbd0c3b6a0d8f79'}
files={name:(SOURCE/name).read_bytes() for name in EXPECTED}
for name,data in files.items():
 if hashlib.sha256(data).hexdigest()!=EXPECTED[name]:raise ValueError('Unexpected source: '+name)
spec=importlib.util.spec_from_file_location('terrain_reader',ROOT/'scripts/extract-warcraft-terrain.py');reader=importlib.util.module_from_spec(spec);spec.loader.exec_module(reader)
t=reader.read_w3e(files['war3map.w3e']);p=reader.read_wpm(files['war3map.wpm'])
d=files['war3map.doo'];count=struct.unpack_from('<I',d,12)[0];offset=16;placements=[]
if d[:4]!=b'W3do' or struct.unpack_from('<II',d,4)!=(8,11):raise ValueError('Unsupported doodad header')
for index in range(count):
 raw=d[offset:offset+4].decode('ascii');variation,x,y,z,angle,sx,sy,sz=struct.unpack_from('<Ifffffff',d,offset+4)
 # This 1.36 map includes the reforged skin fourcc before flags/life.
 skin=d[offset+36:offset+40].decode('ascii');flags,life,table,sets=struct.unpack_from('<BBiI',d,offset+40);offset+=50
 for _ in range(sets):
  items=struct.unpack_from('<I',d,offset)[0];offset+=4+items*8
 editor=struct.unpack_from('<I',d,offset)[0];offset+=4
 placements.append(dict(id=editor,rawId=raw,skin=skin,x=round(x/128,4),z=round(-y/128,4),height=round(z/128,4),scale=round(sx,4),scaleY=round(sz,4),angle=round(angle,5),variation=variation,flags=flags,life=life))
if offset+8!=len(d):raise ValueError('Unexpected doodad trailer')
script=files['war3map.j'].decode('utf8',errors='replace');regions={}
for name,args in re.findall(r'set\s+gg_rct_(\w+)\s*=\s*Rect\(([^)]*)\)',script):
 a,b,c,d=[float(v.replace(' ','')) for v in args.split(',')]
 regions[name]=dict(minX=a/128,maxX=c/128,minZ=-d/128,maxZ=-b/128,x=(a+c)/256,z=-(b+d)/256,native=[a,b,c,d])
starts=[]
for slot,x,y in re.findall(r'DefineStartLocation\((\d+),([^,]+),([^)]*)\)',script):
 starts.append(dict(slot=int(slot),x=float(x.replace(' ',''))/128,z=-float(y.replace(' ',''))/128))
result=dict(provenance=dict(map='Star Wars Blood Tournament 6.4d',author='Billy-Jack / Baal',source='https://www.epicwar.com/maps/331579/',video='https://www.youtube.com/watch?v=QdDI60ckoxo',mapSha256='f7d3ce48b89b8dc6249cfd37bd7dfabba2b17cd957d077d625b736b7fb009a71',hashes=EXPECTED,nativePlayers=8,nativeDoodads=count,coordinates='x=nativeX/128;z=-nativeY/128; vertex row advances nativeY so worldZ decreases',versionMatch='Same SW Blood Tournament family and matching three-patch private pods; exact video map version not stated. Numeric reference only, no native models/textures/scripts copied.'),width=t['width'],height=t['height'],origin=[t['offset'][0]/128,-t['offset'][1]/128],step=1,textures=t['ground'],cliffs=t['cliffs'],tiles=''.join(format(v['texture'],'x') for v in t['vertices']),relief=''.join(format(v['layer'],'x') for v in t['vertices']),heights=[round(v['height']/128,4) for v in t['vertices']],water=''.join('1' if v['flags']&0x40 else '0' for v in t['vertices']),pathing=dict(width=p['width'],height=p['height'],step=.25,flags=p['data'].hex(),unwalkableBit=2),placements=placements,regions=regions,starts=starts)
(ROOT/'shared/bloody-terrain-data.js').write_text('// Generated by scripts/extract-bloody-terrain.py; numeric reference, original voxel art is separate.\nexport const BLOODY_TERRAIN_DATA=Object.freeze('+json.dumps(result,separators=(',',':'))+');\n',encoding='utf8')
print('Exported',t['width'],t['height'],'vertices',len(placements),'doodads',len(regions),'regions',len(starts),'native slots')
